// Package ledger is demo_v00001's dedicated STORAGE realm: it owns the
// token balances, the tokenized-by audit trail, and the dynamic attribute
// map for the standalone demo token. It holds no issuance LOGIC of its own
// — trade rules, admin gating of Tokenize/Detokenize/Transfer, and unit
// formatting all live in the paired
// gno.land/r/g172tf235svs0hkckys8kshnam6ncz7pscx9x59f/demo/demo_v00001/main realm.
//
// ─── STANDALONE: NO DEPENDENCY ON THE REST OF THIS PROJECT ─────────────────────
//
//	This realm and its paired `main` realm are a self-contained demo pair:
//	neither imports anything else from this repository (no `tokenengine`, no
//	`productinterface`, no `market_vXXXXX`, no `orderbook`). Every field and
//	function here is a from-scratch copy of the same shape used by the
//	carbon-credit products' own `<sku>_ledger` realms, kept intentionally
//	independent so this pair can be read, deployed, and understood entirely
//	on its own. There is no locking layer and no marketplace-facing
//	Lock/Unlock/MarketMove/MarketSpend here at all — this demo only
//	showcases tokenization, detokenization, and holder-to-holder transfer;
//	see `main.gno`'s package doc.
//
// ─── EXACTLY ONE TRUSTED CALLER ────────────────────────────────────────────────
//
//	Every mutating function here is gated on the same check: the immediate
//	calling realm must be this pair's own `main` realm, registered once via
//	SetMainRealm. This realm never trusts anything else.
package ledger

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

var (
	admin address

	// mainRealm is the ONE realm allowed to call every mutating function
	// below: gno.land/r/g172tf235svs0hkckys8kshnam6ncz7pscx9x59f/demo/demo_v00001/main.
	mainRealm    address
	mainRealmSet bool

	dynamicAttrs  *avl.Tree // key(string) → value(string)
	tokenBalances *avl.Tree // address.String() → uint64 (total balance)
	tokenizedBy   *avl.Tree // address.String() → uint64 (cumulative gross issuance)
)

func init() {
	admin = unsafe.OriginCaller()
	dynamicAttrs = avl.NewTree()
	dynamicAttrs.Set("status", "active")
	dynamicAttrs.Set("unit", "DEMO")
	tokenBalances = avl.NewTree()
	tokenizedBy = avl.NewTree()
}

// ─── Admin / wiring ─────────────────────────────────────────────────────────────

func SetAdmin(cur realm, newAdmin address) {
	assertAdmin()
	admin = newAdmin
}

func GetAdmin() string { return admin.String() }

// SetMainRealm points this ledger's write access at `m`, this pair's paired
// `main` realm. Admin-only. Must be called once after both this realm and
// `main` are deployed, before ANY mutating call here can succeed.
func SetMainRealm(cur realm, m address) {
	assertAdmin()
	mainRealm = m
	mainRealmSet = true
	chain.Emit("MainRealmChanged", "mainRealm", m.String())
}

func GetMainRealm() string {
	if !mainRealmSet {
		return ""
	}
	return mainRealm.String()
}

// ─── Dynamic attribute CRUD (main-realm-only) ────────────────────────────────────

func SetDynamicAttr(cur realm, key, value string) {
	assertMainRealm()
	if key == "" {
		panic("key must not be empty")
	}
	dynamicAttrs.Set(key, value)
}

func RemoveDynamicAttr(cur realm, key string) {
	assertMainRealm()
	dynamicAttrs.Remove(key)
}

func GetDynamicAttr(key string) string {
	val := dynamicAttrs.Get(key)
	if val == nil {
		return ""
	}
	return val.(string)
}

func HasDynamicAttr(key string) bool {
	return dynamicAttrs.Has(key)
}

func DynamicAttrCount() int { return dynamicAttrs.Size() }

// RenderDynamicAttrs returns a Markdown table of every dynamic attribute, for
// the main realm's own Render(path) to embed directly.
func RenderDynamicAttrs() string {
	out := "| Key | Value |\n|:----|:------|\n"
	dynamicAttrs.Iterate("", "", func(key string, value interface{}) bool {
		out += ufmt.Sprintf("| %s | %s |\n", key, value.(string))
		return false
	})
	return out
}

// ─── Balances (main-realm-only mutations) ────────────────────────────────────────

// MintTo credits `amount` base units to `addr`. Called by `main` from
// Tokenize (new issuance) or as one half of Transfer (net zero).
func MintTo(cur realm, addr address, amount uint64) {
	assertMainRealm()
	mintTo(addr, amount)
}

// BurnFrom debits `amount` base units from `addr`. Called by `main` from
// Detokenize (retirement) or as one half of Transfer (net zero).
func BurnFrom(cur realm, addr address, amount uint64) {
	assertMainRealm()
	burnFrom(addr, amount)
}

// AddTokenized raises addr's cumulative gross issuance figure by `amount`.
// Called by `main` from Tokenize only.
func AddTokenized(cur realm, addr address, amount uint64) {
	assertMainRealm()
	tokenizedBy.Set(addr.String(), TokenizedByOf(addr)+amount)
}

// ─── Queries (plain reads, ungated) ──────────────────────────────────────────────

func BalanceOf(addr address) uint64 {
	val := tokenBalances.Get(addr.String())
	if val == nil {
		return 0
	}
	return val.(uint64)
}

// TokenizedByOf returns the CUMULATIVE GROSS amount ever issued to `addr`.
func TokenizedByOf(addr address) uint64 {
	val := tokenizedBy.Get(addr.String())
	if val == nil {
		return 0
	}
	return val.(uint64)
}

// ─── Internal helpers ─────────────────────────────────────────────────────────

func assertAdmin() {
	if unsafe.OriginCaller() != admin {
		panic("unauthorized: caller is not the admin")
	}
}

// assertMainRealm authorizes every mutating function above, checked against
// the IMMEDIATE calling realm via unsafe.PreviousRealm() (a stack-walker;
// NOT cur.Previous(), which is unimplemented on this toolchain). Safe here
// because `main` always calls this ledger directly, with no intervening
// indirection — there is no capability/marketplace hop in this demo pair.
func assertMainRealm() {
	if !mainRealmSet {
		panic("main realm not registered")
	}
	if unsafe.PreviousRealm().Address() != mainRealm {
		panic("unauthorized: caller is not the registered main realm")
	}
}

func mintTo(addr address, amount uint64) {
	cur := BalanceOf(addr)
	tokenBalances.Set(addr.String(), cur+amount)
}

func burnFrom(addr address, amount uint64) {
	cur := BalanceOf(addr)
	if cur < amount {
		panic("insufficient balance: have " + strconv.FormatUint(cur, 10) +
			", need " + strconv.FormatUint(amount, 10))
	}
	tokenBalances.Set(addr.String(), cur-amount)
}

package ledger

// ─────────────────────────────────────────────────────────────────────────────
// VERSION-SENSITIVE TEST SHIMS — same caveats as the other realms' tests in
// this repo. See any carbon-credit product's ledger_test.gno for the full
// rundown; this file is a standalone copy, so it repeats the essentials.
// ─────────────────────────────────────────────────────────────────────────────

import (
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
)

func setCaller(a address) {
	testing.SetOriginCaller(a)
	testing.SetRealm(testing.NewUserRealm(a))
}

func mkaddr(name string) address { return testutils.TestAddress(name) }

// resetState puts the ledger back into a known, isolated state for each test.
func resetState() {
	admin = mkaddr("admin")
	mainRealm = address("")
	mainRealmSet = false
	dynamicAttrs = avl.NewTree()
	dynamicAttrs.Set("status", "active")
	dynamicAttrs.Set("unit", "DEMO")
	tokenBalances = avl.NewTree()
	tokenizedBy = avl.NewTree()
}

func expectPanic(t *testing.T, name string, fn func()) {
	t.Helper()
	// fn calls a crossing function (Fn(cross, ...)). A panic raised across a realm
	// boundary becomes an "abort" that plain recover() cannot catch — only the
	// revive() builtin can. revive(fn) runs fn and returns the abort value
	// (non-nil) if it aborted, nil if it did not.
	if revive(fn) == nil {
		t.Errorf("%s: expected panic, got none", name)
	}
}

// mainRealmPath: assertMainRealm is gated on PreviousRealm().Address(), which
// only resolves to a CODE realm across a cross call, so we impersonate via
// NewCodeRealm rather than a user address.
const mainRealmPath = "gno.land/r/g172tf235svs0hkckys8kshnam6ncz7pscx9x59f/demo/demo_v00001/main"

func registerMainRealm() address {
	a := testing.NewCodeRealm(mainRealmPath).Address()
	mainRealm = a
	mainRealmSet = true
	return a
}

// seed credits `addr` directly (white-box) so tests don't need a real MintTo
// call through the main realm.
func seed(addr address, amount uint64) {
	tokenBalances.Set(addr.String(), BalanceOf(addr)+amount)
}

// ─── Wiring gates ────────────────────────────────────────────────────────────

func TestSetAdmin_AdminOnly(cur realm, t *testing.T) {
	resetState()
	setCaller(mkaddr("mallory"))
	expectPanic(t, "non-admin SetAdmin", func() { SetAdmin(cross(cur), mkaddr("x")) })
}

func TestSetMainRealm_AdminOnly(cur realm, t *testing.T) {
	resetState()
	setCaller(mkaddr("mallory"))
	expectPanic(t, "non-admin SetMainRealm", func() { SetMainRealm(cross(cur), mkaddr("x")) })
}

// ─── Every mutation: main-realm-only ─────────────────────────────────────────────

func TestMutatingFns_RejectNonMainRealmCaller(cur realm, t *testing.T) {
	resetState()
	registerMainRealm()
	owner := mkaddr("owner")
	seed(owner, 100)

	setCaller(mkaddr("mallory"))
	expectPanic(t, "MintTo non-main-realm", func() { MintTo(cross(cur), owner, 10) })
	expectPanic(t, "BurnFrom non-main-realm", func() { BurnFrom(cross(cur), owner, 10) })
	expectPanic(t, "AddTokenized non-main-realm", func() { AddTokenized(cross(cur), owner, 10) })
	expectPanic(t, "SetDynamicAttr non-main-realm", func() { SetDynamicAttr(cross(cur), "k", "v") })
	expectPanic(t, "RemoveDynamicAttr non-main-realm", func() { RemoveDynamicAttr(cross(cur), "status") })
}

func TestMintTo_ViaMainRealm(cur realm, t *testing.T) {
	resetState()
	registerMainRealm()
	owner := mkaddr("owner")

	testing.SetRealm(testing.NewCodeRealm(mainRealmPath)) // become the main realm in THIS frame
	MintTo(cross(cur), owner, 100)
	if got := BalanceOf(owner); got != 100 {
		t.Errorf("balance = %d, want 100", got)
	}

	testing.SetRealm(testing.NewCodeRealm(mainRealmPath))
	AddTokenized(cross(cur), owner, 100)
	if got := TokenizedByOf(owner); got != 100 {
		t.Errorf("tokenizedBy = %d, want 100", got)
	}
}

func TestBurnFrom_ViaMainRealm(cur realm, t *testing.T) {
	resetState()
	registerMainRealm()
	owner := mkaddr("owner")
	seed(owner, 100)

	testing.SetRealm(testing.NewCodeRealm(mainRealmPath))
	BurnFrom(cross(cur), owner, 40)
	if got := BalanceOf(owner); got != 60 {
		t.Errorf("balance = %d, want 60", got)
	}

	testing.SetRealm(testing.NewCodeRealm(mainRealmPath))
	expectPanic(t, "burn over balance", func() { BurnFrom(cross(cur), owner, 1000) })
}

func TestDynamicAttrs_ViaMainRealm(cur realm, t *testing.T) {
	resetState()
	registerMainRealm()

	testing.SetRealm(testing.NewCodeRealm(mainRealmPath))
	SetDynamicAttr(cross(cur), "description", "A standalone demo token.")
	if got := GetDynamicAttr("description"); got != "A standalone demo token." {
		t.Errorf("description = %q, want the seeded text", got)
	}
	if !HasDynamicAttr("description") {
		t.Error("HasDynamicAttr(description) = false, want true")
	}

	testing.SetRealm(testing.NewCodeRealm(mainRealmPath))
	RemoveDynamicAttr(cross(cur), "description")
	if HasDynamicAttr("description") {
		t.Error("description should be removed")
	}
}

// Package main implements a STANDALONE demo token realm: platform-issued
// tokenization, self-service detokenization, and holder-to-holder transfer,
// with admin-settable trade rules and a dynamic-attribute record — the same
// token-lifecycle shape the carbon-credit products use, minus everything
// marketplace-related.
//
// ─── STANDALONE: NO DEPENDENCY ON THE REST OF THIS PROJECT ─────────────────────
//
//	This realm and its paired
//	gno.land/r/g172tf235svs0hkckys8kshnam6ncz7pscx9x59f/demo/demo_v00001/ledger realm import NOTHING
//	else from this repository — no `tokenengine`, no `productinterface`, no
//	`market_vXXXXX`, no `orderbook`. Every trade-rule check, admin gate, and
//	unit-formatting helper that the carbon-credit products get from the
//	shared `gno.land/p/promex/core/tokenengine` package is copied here
//	directly instead, as plain package-level functions and vars, so this
//	pair is fully self-contained: read it, deploy it, and understand it
//	without needing anything else in this repo to exist.
//
// ─── NO MARKETPLACE FUNCTIONS AT ALL ───────────────────────────────────────────
//
//	There is no `ConnectMarket`, no capability value, no `Lock`/`Unlock`/
//	`MarketMove`/`MarketSpend`, and the ledger has no locking layer — this
//	demo only shows Tokenize / Detokenize / Transfer and the read-only
//	queries around them. `LockedOf`/`SpendableOf` don't exist here because
//	nothing ever reserves a balance; `SpendableOf` would just equal
//	`BalanceOf`.
//
// ─── THE LEDGER TRUSTS EXACTLY ONE CALLER: THIS REALM ──────────────────────────
//
//	gno.land/r/g172tf235svs0hkckys8kshnam6ncz7pscx9x59f/demo/demo_v00001/ledger owns the actual token
//	balances, tokenized-by audit trail, and dynamic attributes, and accepts
//	mutating calls ONLY from this realm (registered once via
//	`ledger.SetMainRealm`). Every function below that reads or writes
//	balances or attributes is a thin forwarding call into that ledger.
package main

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/ufmt/v0"

	ledger "gno.land/r/g172tf235svs0hkckys8kshnam6ncz7pscx9x59f/demo/demo_v00001/ledger"
)

// ─── Fixed Product Attributes ─────────────────────────────────────────────────

const (
	// SKU is this demo product's unique identifier.
	SKU       = "DEMO_V00001"
	TokenName = "Demo Token V00001"

	// UnitName is the trading unit of this demo product. It is what a
	// "unit" means everywhere in this realm.
	UnitName = "DEMO"

	// UnitDecimals / UnitScale define the base unit: the smallest
	// indivisible slice of UnitName this realm can represent. All amounts
	// are integers in base units.
	UnitDecimals = 4
	UnitScale    = 10000 // 10 ** UnitDecimals
)

// ─── State ────────────────────────────────────────────────────────────────────

var (
	admin address

	// TotalSupply is the live circulating supply: always exactly the sum of
	// every balance held in the ledger. It starts at zero and moves only
	// with Tokenize (+) and Detokenize (-); Transfer nets to zero.
	totalSupply uint64

	// BurnedTotal is the cumulative amount ever retired via Detokenize. It
	// only ever grows.
	burnedTotal uint64

	// Trade rules (BASE UNITS), admin-settable.
	minTradeSize uint64 // smallest tradeable amount
	minIncrement uint64 // amounts must sit on this ladder above minTradeSize
)

func init() {
	admin = unsafe.OriginCaller()
	minTradeSize = UnitScale
	minIncrement = UnitScale
}

// ─── Admin ────────────────────────────────────────────────────────────────────

func SetAdmin(cur realm, newAdmin address) {
	assertAdmin()
	admin = newAdmin
}

func GetAdmin() string { return admin.String() }

// Address returns this realm's own on-chain address — what this realm's
// admin passes to ledger.SetMainRealm.
func Address() string { return unsafe.CurrentRealm().Address().String() }

// LedgerAddress returns this pair's ledger realm's own on-chain address,
// once that ledger has registered this realm via SetMainRealm (empty string
// until then).
func LedgerAddress() string { return ledger.GetMainRealm() }

// ─── Trade rules ──────────────────────────────────────────────────────────────

// SetTradeRules configures the product's minimum trade size and minimum
// increment, both in BASE UNITS. Admin-only.
//
//	1 unit minimum, 1 unit increment   → SetTradeRules(10000, 10000)
//	1 unit minimum, 0.2 unit increment → SetTradeRules(10000, 2000)
//
// The rules apply to EVERY amount that moves: Tokenize, Detokenize, and
// Transfer.
func SetTradeRules(cur realm, newMinTradeSize, newMinIncrement uint64) {
	assertAdmin()
	if newMinTradeSize == 0 {
		panic("minTradeSize must be greater than 0")
	}
	if newMinIncrement == 0 {
		panic("minIncrement must be greater than 0")
	}
	minTradeSize = newMinTradeSize
	minIncrement = newMinIncrement

	chain.Emit("TradeRulesUpdated",
		"sku", SKU,
		"minTradeSize", FormatUnits(newMinTradeSize),
		"minIncrement", FormatUnits(newMinIncrement),
	)
}

func MinTradeSize() uint64 { return minTradeSize }
func MinIncrement() uint64 { return minIncrement }

// IsValidTradeAmount reports whether `amount` (base units) satisfies the
// product's trade rules: at least minTradeSize, and on the minIncrement
// ladder above it.
func IsValidTradeAmount(amount uint64) bool {
	if amount == 0 || amount < minTradeSize {
		return false
	}
	if minIncrement == 0 {
		return false
	}
	return (amount-minTradeSize)%minIncrement == 0
}

// CheckTradeAmount panics with a descriptive message unless `amount`
// satisfies the product's trade rules. Every amount-moving entry point
// calls it.
func CheckTradeAmount(amount uint64) {
	if amount == 0 {
		panic("amount must be greater than 0")
	}
	if amount < minTradeSize {
		panic("amount below minimum trade size: min " +
			FormatUnits(minTradeSize) + " " + UnitName +
			", got " + FormatUnits(amount) + " " + UnitName)
	}
	if (amount-minTradeSize)%minIncrement != 0 {
		panic("amount not on the increment ladder: min " +
			FormatUnits(minTradeSize) + " " + UnitName +
			" plus a multiple of " + FormatUnits(minIncrement) + " " + UnitName +
			", got " + FormatUnits(amount) + " " + UnitName)
	}
}

// ─── Dynamic Attribute CRUD ───────────────────────────────────────────────────

func SetDynamicAttr(cur realm, key, value string) {
	if unsafe.OriginCaller() != address(GetAdmin()) {
		panic("unauthorized: caller is not the admin")
	}
	ledger.SetDynamicAttr(cross(cur), key, value)
}

func RemoveDynamicAttr(cur realm, key string) {
	if unsafe.OriginCaller() != address(GetAdmin()) {
		panic("unauthorized: caller is not the admin")
	}
	ledger.RemoveDynamicAttr(cross(cur), key)
}

func GetDynamicAttr(key string) string { return ledger.GetDynamicAttr(key) }

func HasDynamicAttr(key string) bool { return ledger.HasDynamicAttr(key) }

func DynamicAttrCount() int { return ledger.DynamicAttrCount() }

// ─── Tokenization (admin-only, issued straight to the holder) ─────────────────

// Tokenize mints `amount` base units DIRECTLY into `holder`'s wallet and
// raises the circulating supply by the same amount.
//
// ADMIN-ONLY. Ownership is immediate: the tokens are credited to `holder` in
// this same transaction, so there is no window in which the admin holds
// them.
//
// There is NO on-chain supply ceiling. `amount` is in BASE UNITS and must
// satisfy the product's trade rules.
func Tokenize(cur realm, holder address, amount uint64) {
	if unsafe.OriginCaller() != address(GetAdmin()) {
		panic("unauthorized: caller is not the admin")
	}
	if holder == address("") {
		panic("holder must not be empty")
	}
	CheckTradeAmount(amount)

	ledger.MintTo(cross(cur), holder, amount) // credited straight to the holder
	ledger.AddTokenized(cross(cur), holder, amount)
	totalSupply += amount

	chain.Emit("Tokenized",
		"sku", SKU,
		"unit", UnitName,
		"amount", strconv.FormatUint(amount, 10),
		"amountFormatted", FormatUnits(amount),
		"holder", holder.String(),
		"recipient", holder.String(),
		"issuer", GetAdmin(),
		"totalSupply", strconv.FormatUint(totalSupply, 10),
		"tokenizedByHolder", strconv.FormatUint(TokenizedBy(holder), 10),
	)
}

// Detokenize burns `amount` base units from the CALLER's own wallet,
// lowering the circulating supply.
//
// HOLDER-ONLY and self-service: there is no holder parameter, so an address
// can only ever retire its own tokens. Not even the admin can retire someone
// else's.
//
// `deliveryAddr` is an arbitrary off-chain destination string (e.g. for a
// retirement certificate) — this demo does not interpret it.
func Detokenize(cur realm, amount uint64, deliveryAddr string) {
	if deliveryAddr == "" {
		panic("deliveryAddr must not be empty")
	}
	CheckTradeAmount(amount)

	holder := unsafe.OriginCaller()
	if BalanceOf(holder) < amount {
		panic("amount exceeds balance")
	}
	ledger.BurnFrom(cross(cur), holder, amount)
	totalSupply -= amount
	burnedTotal += amount

	chain.Emit("Detokenized",
		"sku", SKU,
		"unit", UnitName,
		"amount", strconv.FormatUint(amount, 10),
		"amountFormatted", FormatUnits(amount),
		"holder", holder.String(),
		"redeemer", holder.String(),
		"deliveryAddr", deliveryAddr,
		"totalSupply", strconv.FormatUint(totalSupply, 10),
		"burnedTotal", strconv.FormatUint(burnedTotal, 10),
	)
}

// ─── Token Operations ─────────────────────────────────────────────────────────

// Transfer sends `amount` base units from the caller to `to`. The amount
// must satisfy the product's trade rules.
func Transfer(cur realm, to address, amount uint64) {
	CheckTradeAmount(amount)
	from := unsafe.OriginCaller()
	if from == to {
		panic("cannot transfer to self")
	}
	if BalanceOf(from) < amount {
		panic("amount exceeds balance")
	}
	ledger.BurnFrom(cross(cur), from, amount)
	ledger.MintTo(cross(cur), to, amount)

	chain.Emit("Transfer",
		"sku", SKU,
		"unit", UnitName,
		"from", from.String(),
		"to", to.String(),
		"amount", strconv.FormatUint(amount, 10),
		"amountFormatted", FormatUnits(amount),
	)
}

// ─── Token Queries ────────────────────────────────────────────────────────────

// TotalSupply is the live circulating supply, in base units. It starts at
// zero, rises with Tokenize, and falls with Detokenize.
func TotalSupply() uint64 { return totalSupply }

// BurnedTotal is the cumulative amount ever retired via Detokenize.
func BurnedTotal() uint64 { return burnedTotal }

func BalanceOf(addr address) uint64 { return ledger.BalanceOf(addr) }

// TokenizedBy returns the CUMULATIVE GROSS amount ever issued to `addr`. It
// never decreases (transfers and retirements do not reduce it).
func TokenizedBy(addr address) uint64 { return ledger.TokenizedByOf(addr) }

func SKU_() string       { return SKU }
func TokenName_() string { return TokenName }
func UnitName_() string  { return UnitName }
func UnitScale_() uint64 { return UnitScale }

// ─── Unit formatting ──────────────────────────────────────────────────────────

// FormatUnits renders base units as a decimal string in UnitName terms:
// 10000 → "1", 2000 → "0.2". Trailing zeros are trimmed.
func FormatUnits(base uint64) string {
	whole := base / UnitScale
	frac := base % UnitScale
	out := strconv.FormatUint(whole, 10)
	if frac == 0 {
		return out
	}
	fs := strconv.FormatUint(frac, 10)
	for len(fs) < UnitDecimals {
		fs = "0" + fs
	}
	for len(fs) > 0 && fs[len(fs)-1] == '0' {
		fs = fs[:len(fs)-1]
	}
	return out + "." + fs
}

// ParseUnits converts a decimal string in UnitName terms to base units:
// "1" → 10000, "0.2" → 2000. Panics on malformed input or on more decimal
// places than the product supports, rather than silently rounding.
func ParseUnits(s string) uint64 {
	if s == "" {
		panic("malformed amount: empty")
	}
	intPart := s
	fracPart := ""
	dot := -1
	for i := 0; i < len(s); i++ {
		if s[i] == '.' {
			if dot >= 0 {
				panic("malformed amount: multiple decimal points in " + s)
			}
			dot = i
		}
	}
	if dot >= 0 {
		intPart = s[:dot]
		fracPart = s[dot+1:]
	}
	if intPart == "" {
		panic("malformed amount: no integer part in " + s)
	}
	assertDigits(intPart, s)
	if len(fracPart) > UnitDecimals {
		panic("too many decimal places for " + UnitName + " (max " +
			strconv.Itoa(UnitDecimals) + "): " + s)
	}
	whole, err := strconv.ParseUint(intPart, 10, 64)
	if err != nil {
		panic("malformed amount: out of range in " + s)
	}
	frac := uint64(0)
	if fracPart != "" {
		assertDigits(fracPart, s)
		padded := fracPart
		for len(padded) < UnitDecimals {
			padded += "0"
		}
		frac, err = strconv.ParseUint(padded, 10, 64)
		if err != nil {
			panic("malformed amount: bad fraction in " + s)
		}
	}
	return whole*UnitScale + frac
}

func assertDigits(part, whole string) {
	for i := 0; i < len(part); i++ {
		if part[i] < '0' || part[i] > '9' {
			panic("malformed amount: non-numeric in " + whole)
		}
	}
}

